local ActionDarkDreamMainStarCell = Class('ActionDarkDreamMainStarCell')
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
local MaxStar = 3

function ActionDarkDreamMainStarCell:__init()
    self.data = nil
    self.index = nil
    self.clickCallBack = nil
    self.groupId = nil
end

function ActionDarkDreamMainStarCell:__delete()
    self.data = nil
    self.index = nil
    self.clickCallBack = nil
    self.groupId = nil
end

function ActionDarkDreamMainStarCell:SetIndex(index,nodeIndex)
    self.index = index
    self.nodeIndex = nodeIndex
end

function ActionDarkDreamMainStarCell:Awake()
    self:InitStarList()
    self:AddUIClick()
end

function ActionDarkDreamMainStarCell:AddUIClick()
    SetButtonAction(self.controller.gameObject,Bind(self,self.OnBtnNodeClick))
end

function ActionDarkDreamMainStarCell:ClickCallBack()
    if not isNull(self.clickCallBack) then
        self.clickCallBack()
    end
end

function ActionDarkDreamMainStarCell:OnBtnNodeClick()
    if checkNumber(self.data.passed) == 1 then
        self:ClickCallBack()
        UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamLevelDetails, parameters = { data = self.data,groupId = self.groupId}},{ { id = Constants.UITypeIds.ActionDarkDreamMainDialog } })
        return
    end

    if self.isUnLock then
        self:ClickCallBack()
        UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamLevelDetails, parameters = { data = self.data,groupId = self.groupId}},{ { id = Constants.UITypeIds.ActionDarkDreamMainDialog } })
    else
        GameUtils.Toast(localize("请通关前置关卡"))
    end
end

function ActionDarkDreamMainStarCell:InitStarList()
    if self.StarList then
        local env = CfUtils.GetLuaScr(self.StarList,"Game.UI.FightReady.ChaoticRecall.ActionDarkDreamStarRoot")
        if not isNull(env) then
            self.starEnv = env
        end
    end
end

function ActionDarkDreamMainStarCell:RefreshShow(data,isLast,callBack,groupId,isRed)
    KTool.SetActive(self.UIFX_SpecialGlow.gameObject,false)
    KTool.SetActive(self.UIFX_LoopGlow.gameObject,false)

    self.data = data
    self.groupId = groupId
    self.clickCallBack = callBack
    if self.index == 1 and not isLast then
        KTool.SetActive(self.ImgLine2.gameObject,false)
    else
        KTool.SetActive(self.ImgLine2.gameObject,not isLast)
    end

    CfUtils.SetUISwitchImage(self.ImgBg,isRed and 2 or 1)
    local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(self.data.id)
    self.nodeVo = nodeVo
    self:SetHardNode()
    local num = self.data.nodeId
    if checkNumber(num) < 10 then
        num = string.format("0%s",num)
    end


    local isPass = checkNumber(self.data.passed) == 1


    local isSkipLevel = self:IsSkipLevel(groupId)
    if isSkipLevel then
        local isAllPass = self:IsAllPass()
        if isAllPass then
            KTool.SetActive(self.SkipLevelTips.gameObject,false)
        else
            KTool.SetActive(self.SkipLevelTips.gameObject,true)
        end
    else
        KTool.SetActive(self.SkipLevelTips.gameObject,false)
    end

    if isPass then
        KTool.SetActive(self.LockNode.gameObject,false)
        CfUtils.PlayAnimation(self.controller.gameObject,"ActionDarkDreamMainDialog_UnLockDefault")
        KTool.SetActive(self.SelectedNode.gameObject,true)
        CfUtils.FillText(self.TxtLvNumUnLock,num)
        self:RefreshStarShow()
    else

        local isUnLock = checkNumber(nodeVo.unlockPlace) == 0 and true or ChaoticRecallUtils.GetIsPassById(nodeVo.groupId,nodeVo.unlockPlace)
        self.isUnLock = isUnLock
        KTool.SetActive(self.LockNode.gameObject,not isUnLock)
        KTool.SetActive(self.SelectedNode.gameObject,isUnLock)
        if isUnLock then
            CfUtils.PlayAnimation(self.controller.gameObject,"ActionDarkDreamMainDialog_UnLockDefault")
            CfUtils.FillText(self.TxtLvNumUnLock,num)
            self:RefreshStarShow()
            KTool.SetActive(self.UIFX_SpecialGlow.gameObject,true)
        else
            CfUtils.PlayAnimation(self.controller.gameObject,"ActionDarkDreamMainDialog_LockDefault")
            CfUtils.FillText(self.TxtLvNumLock,num)
        end
    end
end

function ActionDarkDreamMainStarCell:SetHardNode()
    local isHardNode = not isNull(self.nodeVo.hardLevels)
    KTool.SetActive(self.EmptyBox.gameObject,not isHardNode)
    KTool.SetActive(self.HardStarList.gameObject,isHardNode)
    if isHardNode then
        for i = 1, 2 do
            local addStar = self["AddStar"..i]
            if addStar then
                local light = addStar.transform:Find("ImgLight")
                local isPass = self.data.hardPassed[i] == 1
                KTool.SetActive(light.gameObject,isPass)
            end
        end
    end
end

function ActionDarkDreamMainStarCell:IsAllPass()
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    local tempData = dojo:GetGroups()
    for i, v in pairs(tempData) do
        if v.groupId == self.groupId then
            for k, j in pairs(v.nodes) do
                if j.nodeId < self.data.nodeId then
                    local IsFullStar = self:IsFullStar(j.starCompleted)
                    if not IsFullStar then
                        return false
                    end
                end
            end
        end
    end
    return true
end

function ActionDarkDreamMainStarCell:IsFullStar(data)
    for i, v in pairs(data) do
        if v == MaxStar then
            return true
        end
    end
    return false
end

function ActionDarkDreamMainStarCell:IsSkipLevel(groupId)
    local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(groupId)
    return checkNumber(vo.skipLevel) == self.data.nodeId
end

function ActionDarkDreamMainStarCell:RefreshStarShow()
    self.starEnv:RefreshStarShow(self.data.starCompleted)
end

function ActionDarkDreamMainStarCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamMainStarCell